/* ---------- pricing ---------- */
function basePrice(serviceId, listId) { const l = listId ? byId(DB.priceLists, listId) : DB.priceLists.find(x => x.active && x.year === 2026) || DB.priceLists[1]; return l ? (l.prices[serviceId] ?? 0) : 0; }
function priceFor(serviceId, payerId, tierId) {
  const cp = DB.contractPricing.find(c => String(c.payer) === String(payerId) && String(c.tier) === String(tierId));
  if (!cp) { const p = basePrice(serviceId); return { patient: p, payer: 0, total: p, alert: '', source: 'base' }; }
  const ex = cp.exclude[serviceId]; if (ex) return { patient: ex.patient, payer: ex.payer, total: ex.patient + ex.payer, alert: cp.alerts[serviceId] || '', source: 'excluded' };
  for (const f of cp.lists) { const b = basePrice(serviceId, f.list); if (b) { const pt = Math.round(b * f.patient * 100) / 100, py = Math.round(b * f.payer * 100) / 100; return { patient: pt, payer: py, total: pt + py, alert: cp.alerts[serviceId] || '', source: byId(DB.priceLists, f.list)?.code }; } }
  return { patient: 0, payer: 0, total: 0, alert: cp.alerts[serviceId] || '', source: 'none' };
}
function visitTotals(v) {
  const active = v.lines.filter(l => l.status !== 'Cancelled');
  const total = active.reduce((s, l) => s + l.patient + l.payer, 0), patientShare = active.reduce((s, l) => s + l.patient - (l.discount || 0), 0) - (v.discount || 0), payerShare = active.reduce((s, l) => s + l.payer, 0);
  const paid = (v.payments || []).reduce((s, p) => s + p.amount, 0), refunded = (v.refunds || []).reduce((s, r) => s + r.amount, 0);
  const due = Math.round(patientShare * 100) / 100; return { total, patientShare: due, payerShare, paid, refunded, remaining: Math.round((due - paid + refunded) * 100) / 100, discount: (v.discount || 0) + active.reduce((s, l) => s + (l.discount || 0), 0) };
}
const patientOf = v => byId(DB.patients, v.patient);
const visitByAcc = acc => DB.visits.find(v => v.acc === String(acc).trim());
const visitOfSample = sid => DB.visits.find(v => v.samples.some(s => s.id === sid));
const sampleById = sid => { for (const v of DB.visits) { const s = v.samples.find(x => x.id === sid); if (s) return s; } return null; };

/* ---------- reference ranges & flags ---------- */
function resolveRange(tst, patient) {
  if (!tst || !tst.ranges || !tst.ranges.length) return null;
  const age = patient && patient.dob ? ageOf(patient.dob).y : 30; const sex = patient?.sex || 'All'; const cond = patient?.condition || '';
  const fits = r => (r.sex === 'All' || r.sex === sex) && age >= r.ageFrom && age <= r.ageTo;
  return tst.ranges.find(r => r.cond && r.cond === cond && fits(r)) || tst.ranges.find(r => !r.cond && fits(r)) || tst.ranges.find(r => !r.cond) || tst.ranges[0];
}
function rangeText(tst, patient) { if (!tst) return ''; if (tst.type === 'Numeric' || tst.type === 'Formula') { const r = resolveRange(tst, patient); return r ? `${r.low} – ${r.high}${r.cond ? ' (' + r.cond + ')' : ''}` : '—'; } if (tst.values && tst.values.length) return tst.values.filter(v => v.normal && v.v !== '.').map(v => v.v).join(' / ') || '—'; return '—'; }
function flagFor(tst, value, patient) {
  if (value === '' || value == null) return null;
  if (tst.type === 'Numeric' || tst.type === 'Formula') { const r = resolveRange(tst, patient); const v = Number(value); if (!r || isNaN(v)) return null; if (r.panicLow != null && v < r.panicLow) return 'LL'; if (r.panicHigh != null && v > r.panicHigh) return 'HH'; if (v < r.low) return 'L'; if (v > r.high) return 'H'; return 'N'; }
  if (tst.values && tst.values.length) { const d = tst.values.find(x => x.v === value); if (!d) return null; return d.critical ? 'HH' : d.normal ? 'N' : 'A'; }
  return null;
}
function computeFormula(tst, getValue) { if (!tst.formula) return ''; try { let expr = tst.formula.replace(/\{([A-Z0-9_]+)\}/gi, (m, code) => { const v = getValue(code); if (v === '' || v == null || isNaN(Number(v))) throw new Error('missing'); return `(${Number(v)})`; }); if (!/^[\d\s+\-*/().]+$/.test(expr)) return ''; const r = Function('"use strict";return (' + expr + ')')(); return Number.isFinite(r) ? Number(r.toFixed(tst.decimals ?? 1)) : ''; } catch { return ''; } }
function expectedResultDate(from, durationH) { return new Date(new Date(from).getTime() + (durationH || 24) * 36e5); }

